def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            comps.append((color, cells))

    # Find a three-cell straight object and recolor it to the color of the
    # nearest object containing a longer straight run in the same direction.
    targets = []
    for color, cells in comps:
        if len(cells) != 3:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if len(set(rs)) == 1 and sorted(cs) == list(range(min(cs), min(cs) + 3)):
            targets.append((color, cells, "h"))
        elif len(set(cs)) == 1 and sorted(rs) == list(range(min(rs), min(rs) + 3)):
            targets.append((color, cells, "v"))

    for color, cells, direction in targets:
        candidates = []
        for other_color, other_cells in comps:
            if other_color == color:
                continue
            points = set(other_cells)
            longest = 0
            for r, c in points:
                run = 1
                if direction == "h":
                    while (r, c + run) in points:
                        run += 1
                else:
                    while (r + run, c) in points:
                        run += 1
                longest = max(longest, run)
            if longest >= 4:
                dist = min(abs(r1-r2) + abs(c1-c2)
                           for r1, c1 in cells for r2, c2 in other_cells)
                candidates.append((dist, other_color))

        if candidates:
            new_color = min(candidates)[1]
            for r, c in cells:
                out[r][c] = new_color
            break

    return out
